package com.nexacrm.service;  import com.nexacrm.dto.WorkflowDTO; import com.nexacrm.exception.ResourceNotFoundException; import com.nexacrm.model.Workflow; import com.nexacrm.model.WorkflowRunLog; import com.nexacrm.repository.WorkflowRepository; import com.nexacrm.repository.WorkflowRunLogRepository; import com.nexacrm.security.TenantContext; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.util.StringUtils;  import java.time.LocalDateTime; import java.util.Comparator; import java.util.List; import java.util.Map; import java.util.stream.Collectors;  @Service @RequiredArgsConstructor @Transactional public class WorkflowService {      private final WorkflowRepository workflowRepository;     private final WorkflowRunLogRepository workflowRunLogRepository;      private Long tenantId() { return TenantContext.currentTenantId(); }      @Transactional(readOnly = true)     public List<WorkflowDTO> findAll() {         return workflowRepository.findByTenantIdAndDeletedFalse(tenantId()).stream()             .sorted(Comparator.comparing(Workflow::getCreatedAt, Comparator.nullsLast(Comparator.reverseOrder())))             .map(this::toDTO)             .collect(Collectors.toList());     }      public WorkflowDTO create(WorkflowDTO dto) {         validateWorkflowStructure(dto.getSteps());         Workflow workflow = fromDTO(dto);         workflow.setTenantId(tenantId());         if (workflow.getStatus() == null) workflow.setStatus(Workflow.WorkflowStatus.ACTIVE);         if (workflow.getRuns() == null) workflow.setRuns(0);         if (workflow.getLastRun() == null || workflow.getLastRun().isBlank()) workflow.setLastRun("Never");         Workflow saved = workflowRepository.save(workflow);         saveLog(saved, "WORKFLOW_CREATED", "SUCCESS", "Workflow created");         return toDTO(saved);     }      public WorkflowDTO update(String id, WorkflowDTO dto) {         Workflow workflow = workflowRepository.findByIdAndTenantIdAndDeletedFalse(id, tenantId())             .orElseThrow(() -> new ResourceNotFoundException("Workflow not found: " + id));          if (dto.getName() != null) workflow.setName(dto.getName());         if (dto.getCategory() != null) workflow.setCategory(dto.getCategory());         if (dto.getStatus() != null) workflow.setStatus(dto.getStatus());         if (dto.getRuns() != null) workflow.setRuns(dto.getRuns());         if (dto.getLastRun() != null) workflow.setLastRun(dto.getLastRun());         workflow.setPriority(dto.getPriority());         if (dto.getSteps() != null) {             validateWorkflowStructure(dto.getSteps());             workflow.setSteps(dto.getSteps().stream()                 .map(s -> Workflow.WorkflowStep.builder().type(s.getType()).text(s.getText()).build())                 .collect(Collectors.toList()));         }         Workflow saved = workflowRepository.save(workflow);         saveLog(saved, "WORKFLOW_UPDATED", "SUCCESS", "Workflow updated");         return toDTO(saved);     }      public void delete(String id) {         Workflow workflow = workflowRepository.findByIdAndTenantIdAndDeletedFalse(id, tenantId())             .orElseThrow(() -> new ResourceNotFoundException("Workflow not found: " + id));         workflow.setDeleted(true);         workflowRepository.save(workflow);         saveLog(workflow, "WORKFLOW_DELETED", "SUCCESS", "Workflow deleted");     }      public WorkflowDTO toggle(String id) {         Workflow workflow = workflowRepository.findByIdAndTenantIdAndDeletedFalse(id, tenantId())             .orElseThrow(() -> new ResourceNotFoundException("Workflow not found: " + id));         workflow.setStatus(             workflow.getStatus() == Workflow.WorkflowStatus.ACTIVE                 ? Workflow.WorkflowStatus.PAUSED                 : Workflow.WorkflowStatus.ACTIVE         );         Workflow saved = workflowRepository.save(workflow);         saveLog(saved, "WORKFLOW_TOGGLED", "SUCCESS", "Workflow status changed to " + saved.getStatus().name());         return toDTO(saved);     }      @Transactional(readOnly = true)     public List<Map<String, Object>> logs(String id) {         Workflow workflow = workflowRepository.findByIdAndTenantIdAndDeletedFalse(id, tenantId())             .orElseThrow(() -> new ResourceNotFoundException("Workflow not found: " + id));          return workflowRunLogRepository             .findTop100ByWorkflowIdAndTenantIdAndDeletedFalseOrderByRunAtDesc(workflow.getId(), tenantId())             .stream()             .map(log -> {                 Map<String, Object> row = new java.util.LinkedHashMap<>();                 row.put("id", log.getId());                 row.put("workflowId", log.getWorkflowId());                 row.put("workflowName", log.getWorkflowName());                 row.put("trigger", log.getTrigger());                 row.put("status", log.getStatus());                 row.put("message", log.getMessage());                 row.put("runAt", log.getRunAt());                 row.put("createdAt", log.getCreatedAt());                 return row;             })             .collect(Collectors.toList());     }      private void validateWorkflowStructure(List<WorkflowDTO.WorkflowStepDTO> steps) {         if (steps == null || steps.size() < 2) {             throw new IllegalArgumentException("At least 2 workflow steps are required");         }          boolean hasIf = false;         boolean hasThen = false;          for (WorkflowDTO.WorkflowStepDTO step : steps) {             String type = step.getType() != null ? step.getType().trim().toUpperCase() : "";             String text = step.getText() != null ? step.getText().trim() : "";              if (!StringUtils.hasText(type)) {                 throw new IllegalArgumentException("Step type is required");             }             if (!StringUtils.hasText(text)) {                 throw new IllegalArgumentException("Step text is required");             }             if ("IF".equals(type)) hasIf = true;             if ("THEN".equals(type)) hasThen = true;         }          if (!hasIf) throw new IllegalArgumentException("Workflow must include an IF step");         if (!hasThen) throw new IllegalArgumentException("Workflow must include a THEN step");     }      private void saveLog(Workflow workflow, String trigger, String status, String message) {         WorkflowRunLog log = WorkflowRunLog.builder()             .workflowId(workflow.getId())             .workflowName(workflow.getName())             .trigger(trigger)             .status(status)             .message(message)             .runAt(LocalDateTime.now())             .build();         log.setTenantId(tenantId());         workflowRunLogRepository.save(log);     }      private WorkflowDTO toDTO(Workflow workflow) {         return WorkflowDTO.builder()             .id(workflow.getId())             .name(workflow.getName())             .category(workflow.getCategory())             .status(workflow.getStatus())             .runs(workflow.getRuns())             .lastRun(workflow.getLastRun())             .priority(workflow.getPriority())             .steps(workflow.getSteps() == null ? List.of() : workflow.getSteps().stream()                 .map(s -> WorkflowDTO.WorkflowStepDTO.builder().type(s.getType()).text(s.getText()).build())                 .collect(Collectors.toList()))             .createdAt(workflow.getCreatedAt())             .updatedAt(workflow.getUpdatedAt())             .build();     }      private Workflow fromDTO(WorkflowDTO dto) {         return Workflow.builder()             .name(dto.getName())             .category(dto.getCategory())             .status(dto.getStatus())             .runs(dto.getRuns())             .lastRun(dto.getLastRun())             .priority(dto.getPriority())             .steps(dto.getSteps() == null ? List.of() : dto.getSteps().stream()                 .map(s -> Workflow.WorkflowStep.builder().type(s.getType()).text(s.getText()).build())                 .collect(Collectors.toList()))             .build();     } }